<?php
require_once __DIR__ . '/config.php'; require_admin(); verify_csrf(); $pdo=db(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST') {
    $action=$_POST['form_action']??'create';
    if($action==='create') {
        $name=trim($_POST['full_name']??''); $username=trim($_POST['username']??''); $password=$_POST['password']??''; $stage=$_POST['assigned_stage']??'';
        if($name===''||$username===''||strlen($password)<10||!isset(stages()[$stage])) $error='Enter a name, username, valid stage and password of at least 10 characters.';
        else {
            try { $s=$pdo->prepare("INSERT INTO users (full_name,username,password_hash,role,assigned_stage) VALUES (?,?,?,'employee',?)");$s->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$stage]);flash('Employee account created. Share the username and temporary password securely.');redirect('employees.php'); }
            catch(Throwable $e) { $error='Could not create account. Username may already be in use.'; }
        }
    } elseif($action==='toggle') {
        $uid=(int)($_POST['user_id']??0);$s=$pdo->prepare("UPDATE users SET active=IF(active=1,0,1) WHERE id=? AND role='employee'");$s->execute([$uid]);flash('Employee account access updated.');redirect('employees.php');
    } elseif($action==='reset') {
        $uid=(int)($_POST['user_id']??0);$password=$_POST['new_password']??'';
        if(strlen($password)<10) $error='New password must be at least 10 characters.';
        else { $s=$pdo->prepare("UPDATE users SET password_hash=? WHERE id=? AND role='employee'");$s->execute([password_hash($password,PASSWORD_DEFAULT),$uid]);flash('Employee password changed. Share it securely.');redirect('employees.php'); }
    }
}
$users=$pdo->query("SELECT id,full_name,username,role,assigned_stage,active,created_at FROM users ORDER BY role,full_name")->fetchAll();$flash=$_SESSION['flash']??null;unset($_SESSION['flash']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Employees | <?=e(APP_NAME)?></title><link rel="stylesheet" href="assets/style.css"><script defer src="assets/app.js"></script></head><body><div class="app-shell"><aside class="sidebar"><a class="side-brand" href="dashboard.php"><div class="brand-mark">BP</div><div><strong>BOOKPRINTERS</strong><small>& SHREEPUBLICATIONS</small></div></a><div class="side-label">WORKSPACE</div><a class="nav-link" href="dashboard.php"><span>▦</span> Overview</a><a class="nav-link" href="jobs.php"><span>▤</span> Production jobs</a><a class="nav-link active" href="employees.php"><span>♙</span> Employees & access</a><div class="sidebar-bottom"><div class="user-mini"><div class="avatar"><?=e(strtoupper(substr(current_user()['full_name'],0,1)))?></div><div><strong><?=e(current_user()['full_name'])?></strong><small>Administrator</small></div></div><a class="nav-link logout" href="logout.php"><span>↪</span> Sign out</a></div></aside><main class="main"><header class="topbar"><div><p class="eyebrow">WORKSPACE / ACCESS CONTROL</p><h1>Employees & access</h1></div><a class="btn secondary" href="dashboard.php">← Dashboard</a></header><?php if($flash): ?><div class="alert <?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif; ?><?php if($error): ?><div class="alert error"><?=e($error)?></div><?php endif; ?><section class="welcome-row"><div><h2>Manage employee accounts</h2><p class="muted">Each employee sees only their assigned production stage.</p></div></section><div class="two-col"><section class="panel"><div class="panel-heading"><div><h3>Create employee login</h3><p class="muted small">Use a unique username and strong password.</p></div></div><form method="post" class="job-form compact-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="form_action" value="create"><div class="field"><label>Employee full name *</label><input name="full_name" required placeholder="Employee name"></div><div class="field"><label>Username *</label><input name="username" required autocomplete="off" placeholder="e.g. bhoomika.print"></div><div class="field"><label>Assigned stage *</label><select name="assigned_stage" required><option value="">Choose stage</option><?php foreach(stages() as $key=>$stage): ?><option value="<?=e($key)?>"><?=e($stage['label'])?> — <?=e($stage['employee'])?></option><?php endforeach; ?></select></div><div class="field"><label>Initial password (10+ characters) *</label><input type="password" name="password" required minlength="10" autocomplete="new-password"></div><button class="btn primary full" type="submit">＋ Create employee account</button></form></section><section class="panel"><div class="panel-heading"><div><h3>Stage ownership</h3><p class="muted small">Your current production assignments</p></div></div><div class="owner-list"><?php foreach(stages() as $key=>$stage): ?><div class="owner-row"><div class="stage-number"><?=$stage['step']?></div><div><strong><?=e($stage['label'])?></strong><small><?=e($stage['employee'])?></small></div><span class="owner-arrow">→</span></div><?php endforeach; ?></div><p class="hint-box">Rahul Saini has three stages assigned: Cutting, Lamination and Packing. You can create separate logins for each stage, or use one account assigned to one stage at a time.</p></section></div><section class="panel"><div class="panel-heading"><div><h3>All accounts</h3><p class="muted small">Disable access when an employee no longer needs it.</p></div><div class="search-wrap"><span>⌕</span><input id="jobSearch" placeholder="Search employee..."></div></div><div class="table-wrap"><table id="jobsTable"><thead><tr><th>Name</th><th>Username</th><th>Role / stage</th><th>Access</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><div class="book-cell"><div class="avatar"><?=e(strtoupper(substr($u['full_name'],0,1)))?></div><strong><?=e($u['full_name'])?></strong></div></td><td><?=e($u['username'])?></td><td><?=e(ucfirst($u['role']))?><small class="subline"><?=e($u['role']==='admin'?'Full access':(stages()[$u['assigned_stage']]['label']??''))?></small></td><td><span class="status <?=$u['active']?'completed':'pending'?>"><?=$u['active']?'Active':'Disabled'?></span></td><td><?=e(date('d M Y',strtotime($u['created_at'])))?></td><td><?php if($u['role']==='employee'): ?><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="form_action" value="toggle"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><button class="btn small-btn secondary" type="submit"><?=$u['active']?'Disable':'Enable'?></button></form><details class="reset-details"><summary>Reset password</summary><form method="post" class="reset-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="form_action" value="reset"><input type="hidden" name="user_id" value="<?=(int)$u['id']?>"><input type="password" name="new_password" minlength="10" required placeholder="New password (10+)"><button class="btn small-btn primary" type="submit">Save</button></form></details><?php else: ?><span class="muted small">Owner account</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><footer class="footer">© <?=date('Y')?> BookPrinters & ShreePublications <span>Production made visible.</span></footer></main></div></body></html>
